{ public async Task<Result> Handle(VerifyInstructorAuthorizationCommand c,CancellationToken ct){var e=await employees.GetByIdForUpdateAsync(c.OrganizationId,c.EmployeeId,ct);if(e is null)return Result.Failure(EmployeeErrors.NotFound);var r=e.VerifyInstructorAuthorization(c.AuthorizationId,c.VerificationMethod,c.Reason,clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();} }
public sealed class RejectInstructorAuthorizationCommandHandler(IEmployeeRepository employees,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<RejectInstructorAuthorizationCommand>
{ public async Task<Result> Handle(RejectInstructorAuthorizationCommand c,CancellationToken ct){var e=await employees.GetByIdForUpdateAsync(c.OrganizationId,c.EmployeeId,ct);if(e is null)return Result.Failure(EmployeeErrors.NotFound);var r=e.RejectInstructorAuthorization(c.AuthorizationId,c.Reason,clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();} }
